    n, m = map(int, input().split(' '))

    mapp = []

    for a in range(n):
        s = list(input())
        s = [c == "1" for c in s]
        mapp.insert(0, s[1:-1])

    res = None
    #print(mapp)

    empty_floor = n
    while True:
        litup = False
        for x in mapp[empty_floor-1]:
            if x:
                litup = True
                break
        if not litup:
            empty_floor -= 1
        else:
            break
        if empty_floor < 0:
            break

    if empty_floor <= 0:
        return 0

    #print("empty_floor", empty_floor)

    for comb in range(2**(empty_floor-1)):
        temp = 0
        c = bin(comb)[2:]
        c = "0" * ((empty_floor-1)-len(c)) + c
        c = list(c)
        c = [x == "1" for x in c]

        #print("c", c)

        last = False # start from left
        if empty_floor != 1:
            for i, x in enumerate(c):
                if x != last:
                    temp += m+1 + 1
                else:
                    f = None
                    #print(i)
                    #print("last", last)
                    for j, y in enumerate(mapp[i]):
                        if y:
                            f = j
                            if last:
                                break
                    if f is None:
                        temp += 1
                    else:
                        if last:
                            temp += 2 * (m - f) + 1
                        else:
                            temp += 2 * (f + 1) + 1
                last = x


        #final floor:
        f = None
        for j, y in enumerate(mapp[empty_floor-1]):
            if y:
                f = j
                if last:
                    break
        if f is not None:
            #print(f, "f")
            if c[-1]:
                temp += m - f
            else:
                temp += f + 1

        if res is None:
            res = temp
        res = min(res, temp)

        #print(c, temp)


    return res

