    n, m = map(int, input().split())
    room = [[int(i) for i in input()] for j in range(n)]
    room.reverse()

    exits = [False] * n

    for i in range(n - 1, -1, -1):
        if any(room[i]):
            exits[i] = True

        if i - 1 >= 0:
            exits[i - 1] |= exits[i]

    # print(exits)

