def dfs(floor, n, m, room, exits, pos, move):
    nonlocal ans

    k = -1

    if pos == 0:
        for j in range(m + 1, -1, -1):
            if room[floor][j]:
                k = j
                break
        else:
            k = 0
    else:
        for j in range(0, m + 2):
            if room[floor][j]:
                k = j
                break
        else:
            k = m + 1

    move += abs(k - pos)

    if floor == n - 1 or not exits[floor + 1]:
        ans = min(ans, move)
        return
    else:
        dfs(floor + 1, n, m, room, exits, 0, move + k + 1)
        dfs(floor + 1, n, m, room, exits, m + 1, move + m + 1 - k + 1)

