def simulate(n, m, first, last, mask):
    pos = 'left'
    time = 0

    for floor in range(n - 1):
        action = mask & 1
        mask >>= 1

        if pos == 'left':
            if action == 0:
                time += 2 * last[floor]
            else:
                time += m + 1
                pos = 'right'
        else:
            if action == 0:
                time += 2 * (m + 1 - first[floor])
            else:
                time += m + 1
                pos = 'left'

        time += 1

    if pos == 'left':
        time += last[n - 1]
    else:
        time += m + 1 - first[n - 1]

    return time


